  int getImageMaxDimension() =>
      int.parse(getValueWithDefault('IMAGE_MAX_DIMENSION', '8000'));

  /// JPEG quality for image processing.
  /// Key: `IMAGE_JPEG_QUALITY`, default: 0.9. THROWS on invalid.
  double getImageJpegQuality() =>
