 * 
 * @param filePath File path relative to working directory or absolute path within working directory
 * @return File content as UTF-8 string, or null if file doesn't exist or is inaccessible
 */
@MCPTool(
    name = "file_read",
    description = "Read file content from working directory (supports input/ and outputs/ folders). Returns file content as string or null if file doesn't exist or is inaccessible. All file formats supported as UTF-8 text.",
    integration = "file"
)
public String readFile(
        @MCPParam(
            name = "path",
            description = "File path relative to working directory or absolute path within working directory",
            required = true,
            example = "outputs/response.md"
        ) String filePath
) {
    if (filePath == null || filePath.trim().isEmpty()) {
        logger.warn("File path cannot be null or empty");
        return null;
    }

    try {
        // Get working directory (absolute, normalized)
        Path workingDir = Paths.get(System.getProperty("user.dir"))
                .toAbsolutePath()
                .normalize();

        // Parse requested path
        Path requestedPath = Paths.get(filePath.trim());

        // Resolve to absolute path and normalize (handles ./ and ../ components)
        Path resolvedPath;
        if (requestedPath.isAbsolute()) {
            resolvedPath = requestedPath.normalize();
        } else {
            resolvedPath = workingDir.resolve(requestedPath).normalize();
        }

        // Security check: Ensure resolved path is within working directory,
        // OR it matches one of the user-configured allowed path patterns.
        if (!resolvedPath.startsWith(workingDir) && !isAllowedByConfig(resolvedPath, workingDir)) {
            logger.error("Security violation: Path traversal attempt blocked - requested: {}, resolved: {}, working dir: {}", 
                    filePath, resolvedPath, workingDir);
            return null;
        }

        // Check if file exists
        if (!Files.exists(resolvedPath)) {
            logger.warn("File not found: {} (resolved to: {})", filePath, resolvedPath);
            return null;
        }

        // Check if file is readable
        if (!Files.isReadable(resolvedPath)) {
            logger.warn("File not readable: {} (resolved to: {})", filePath, resolvedPath);
            return null;
        }

        // Check if path is a directory
        if (Files.isDirectory(resolvedPath)) {
            logger.warn("Path is a directory, not a file: {} (resolved to: {})", filePath, resolvedPath);
            return null;
        }

        // Read file content as UTF-8 string
        String content = Files.readString(resolvedPath, StandardCharsets.UTF_8);

        logger.debug("Successfully read {} characters from: {} (resolved to: {})", 
                content.length(), filePath, resolvedPath);

        return content;

    } catch (IOException e) {
        logger.error("Failed to read file: {} - {}", filePath, e.getMessage(), e);
        return null;
    } catch (Exception e) {
        logger.error("Unexpected error reading file: {} - {}", filePath, e.getMessage(), e);
        return null;
    }
}

/**
 * Resolves a user supplied path against the working directory and applies the same
 * sandbox rules as {@link #readFile(String)}. Returns null when the path is blank or
 * outside the working directory (and not allowed by configuration).
 */
private Path resolveSandboxedPath(String filePath) {
    if (filePath == null || filePath.trim().isEmpty()) {
        return null;
    }
    Path workingDir = Paths.get(System.getProperty("user.dir")).toAbsolutePath().normalize();
    Path requestedPath = Paths.get(filePath.trim());
    Path resolvedPath = requestedPath.isAbsolute()
            ? requestedPath.normalize()
            : workingDir.resolve(requestedPath).normalize();
    if (!resolvedPath.startsWith(workingDir) && !isAllowedByConfig(resolvedPath, workingDir)) {
        logger.error("Security violation: Path traversal attempt blocked - requested: {}, resolved: {}, working dir: {}",
                filePath, resolvedPath, workingDir);
        return null;
    }
    return resolvedPath;
}

/**
 * Check whether a file or directory exists inside the sandboxed working directory.
 */
@MCPTool(
    name = "file_exists",
    description = "Check whether a file or directory exists in the working directory. Returns true or false (false for paths outside the sandbox).",
    integration = "file"
)
public Boolean fileExists(
        @MCPParam(
            name = "path",
            description = "File or directory path relative to working directory or absolute path within working directory",
            required = true,
            example = "outputs/response.md"
        ) String filePath
) {
    try {
        Path resolved = resolveSandboxedPath(filePath);
        return resolved != null && Files.exists(resolved);
    } catch (Exception e) {
        logger.error("Unexpected error checking file existence: {} - {}", filePath, e.getMessage(), e);
        return false;
    }
}

/**
 * List the direct children of a directory inside the sandboxed working directory.
 */
@MCPTool(
    name = "file_list",
    description = "List the entries of a directory in the working directory. Returns JSON {\"entries\": [absolute paths, sorted]} or null if the path is not a readable directory inside the sandbox.",
    integration = "file"
)
public String listFiles(
        @MCPParam(
            name = "path",
            description = "Directory path relative to working directory or absolute path within working directory",
            required = true,
            example = "outputs"
        ) String dirPath
) {
    try {
        Path resolved = resolveSandboxedPath(dirPath);
        if (resolved == null || !Files.isDirectory(resolved) || !Files.isReadable(resolved)) {
            logger.warn("Directory not listable: {}", dirPath);
            return null;
        }
        org.json.JSONArray entries = new org.json.JSONArray();
        try (java.util.stream.Stream<Path> children = Files.list(resolved)) {
            children.map(c -> c.toAbsolutePath().normalize().toString()).sorted().forEach(entries::put);
        }
        return new JSONObject().put("entries", entries).toString();
    } catch (Exception e) {
        logger.error("Failed to list directory: {} - {}", dirPath, e.getMessage(), e);
        return null;
    }
}

/**
 * Write content to file in working directory.
 * 
 * Creates parent directories automatically if they don't exist.
 * Supports writing to any subdirectory within working directory.
 * 
 * Security Features:
 * - Sandboxed to working directory only
 * - Path traversal prevention (../, absolute paths outside working dir)
 * - Automatic directory creation
 * 
 * @param filePath File path relative to working directory or absolute path within working directory
 * @param content Content to write as UTF-8 string
 * @return Success message or null if operation failed

     *
     * <p>Each raw pattern is resolved relative to {@code workingDir} before matching,
     * so {@code ../.dmtools/**} expands to the sibling {@code .dmtools} directory of
     * the working directory regardless of where the JVM was started.</p>
     *
     * <p>Pattern rules:
