  }

  /// Extra Jira fields to fetch. Key: `JIRA_EXTRA_FIELDS`.
  List<String>? getJiraExtraFields() {
    final v = getValue('JIRA_EXTRA_FIELDS');
    return v == null ? null : v.split(',');
  }

