  Set<String> getJiraIssueAllowedPrefixes() =>
      _parseUpperSetExt(getValue('JIRA_ISSUE_ALLOWED_PREFIXES'));

  /// Story points field keys. Key: `DEFAULT_TICKET_STORY_POINTS_FIELDS`.
