        .map((s) => s.trim().toLowerCase())
        .where((s) => s.isNotEmpty)
        .toSet();
  }

  /// Whether caching is enabled. Key: `DMTOOLS_CACHE_ENABLED`, default: false.
  bool isCacheEnabled() {
    final v = getValue('DMTOOLS_CACHE_ENABLED');
